const inkEditor = createInkEditor({$, icon, esc, id, request, transaction, toast, failure,
  onClose:()=>{page='projects';inChat=true;render(true);},
  onSave:async(doc,blob)=>{
    const p=projects.find(p=>p.id===doc.projectId); if(!p) throw new Error('项目已不存在');
    const existing=messages.find(m=>m.id===doc.id);
    const now=Date.now();
    const m={id:doc.id, projectId:p.id, type:'handwriting', name:doc.title||'手写笔记', pageCount:doc.pages.length, created:existing?.created||now, ...(existing?{edited:now}:{})};
    await transaction(['messages','media','ink','projects'],tx=>{
      tx.objectStore('messages').put(m);tx.objectStore('media').put({id:m.id,blob});
      tx.objectStore('ink').put({...doc,draft:false,sourceId:null,updated:now});
      tx.objectStore('ink').delete(doc.draftId);
      tx.objectStore('projects').put({...p,updated:now});
    });
    revokeMedia(m.id);await refresh();page='projects';inChat=true;render(true);toast(existing?'手写笔记已更新':'手写笔记已保存');
  }
});
const noteEditor=createNoteEditor({$,esc,id,request,transaction,toast,failure,
 onClose:()=>{if(editorReturn){page=editorReturn.page;inChat=editorReturn.inChat;activeId=editorReturn.activeId;}render();},
 onSave:async(kind,pid,source,data)=>{
  const p=projects.find(p=>p.id===pid);if(!p)throw new Error('项目已不存在');const now=Date.now();
  await transaction([kind==='task'?'tasks':'messages','projects','drafts'],tx=>{
   const value=kind==='task'?{id:source?.id||id(),projectId:pid,text:data.text,done:source?.done||false,created:source?.created||now,dueDate:data.dueDate,images:data.images}:{id:source?.id||id(),projectId:pid,type:'richtext',text:data.text,html:data.html,created:source?.created||now,edited:source?now:undefined};
   tx.objectStore(kind==='task'?'tasks':'messages').put(value);tx.objectStore('projects').put({...p,updated:now});tx.objectStore('drafts').delete(data.id);
  });
  if(kind==='task'){orderSnapshot=null;if(!source){clearComposerDraft(pid);$('#message-input')?.remove();}}await refresh();await collectUnusedMedia();toast(kind==='task'?'待办已保存':'笔记已保存');
 }
});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function failure(e){console.error(e);toast(e?.name==='QuotaExceededError'?'设备空间不足，请先备份并清理空间':e?.message||'保存失败，请重试');}
function request(store,method,...args){return new Promise((resolve,reject)=>{const tx=db.transaction(store,['get','getAll'].includes(method)?'readonly':'readwrite');const req=tx.objectStore(store)[method](...args);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error||req.error);tx.onabort=()=>reject(tx.error||new Error('数据操作未完成'));});}
function transaction(stores,mutate){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');try{mutate(tx);}catch(e){tx.abort();reject(e);return;}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('数据操作未完成'));});}
async function refresh(){[projects,messages,tasks,templates]=await Promise.all(['projects','messages','tasks','templates'].map(s=>request(s,'getAll')));if(!projects.some(p=>p.id===activeId))activeId=sortedProjects()[0]?.id;}
function sortedProjects(){return [...projects].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated-a.updated);}
function projectMessages(pid=activeId){return messages.filter(m=>m.projectId===pid).sort((a,b)=>a.created-b.created||a.id.localeCompare(b.id));}
function projectTasks(pid=activeId){return tasks.filter(t=>t.projectId===pid).sort((a,b)=>a.created-b.created||a.id.localeCompare(b.id));}
function project(){return projects.find(p=>p.id===activeId);}
function draft(pid=activeId){let d=drafts.get(pid);if(!d)d={id:pid,text:'',taskText:'',taskMode:false};if(!d.unified){d.text=[d.text||'',d.taskText&&d.taskText!==d.text?d.taskText:''].filter(Boolean).join('\n');d.taskText='';d.unified=true;}drafts.set(pid,d);return d;}
function persistDraft(pid=activeId){const d=structuredClone(draft(pid));pendingDraftWrites=pendingDraftWrites.catch(()=>{}).then(()=>request('drafts','put',d));pendingDraftWrites.catch(failure);}
function rememberDraft(){const input=$('#message-input');if(input&&activeId){draft().text=input.value;draft().taskMode=taskMode;persistDraft();}}
function clearComposerDraft(pid){draft(pid).text='';draft(pid).taskText='';persistDraft(pid);}
function shortTime(ts){const d=new Date(ts);return d.toDateString()===new Date().toDateString()?clockTime(ts):`${d.getMonth()+1}/${d.getDate()}`;}
function clockTime(ts){return new Date(ts).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});}
function dayTime(ts){const d=new Date(ts);return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;}
function preview(m){if(!m)return '还没有记录，发一条消息开始吧';return m.type==='image'?'[图片]':m.type==='video'?'[视频]':m.type==='handwriting'?'[手写] '+m.name:m.type==='task'?'[待办] '+m.text:m.text;}
function projectIcon(emoji){return icon(({'🌱':'leaf','💼':'case','💡':'bulb','🏠':'house','📚':'book','🎯':'target','🎨':'art','🧭':'compass','🛠️':'tools','🎮':'game','✈️':'plane','📝':'note'})[emoji]||'note');}
function avatar(p){const count=tasks.filter(t=>t.projectId===p.id&&!t.done).length;return `<div class="avatar">${projectIcon(p.emoji)}${count?`<span class="pending-badge" aria-label="${count} 项未完成">${count>99?'99+':count}</span>`:''}</div>`;}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'rail'}" aria-label="主导航">${mobile?'':'<img class="brand-icon" src="icon.svg" alt="自言">'}${[['projects','chat','项目'],['tasks','tasks','待办'],['settings','settings','设置']].map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-top"><div class="title-row"><h1>自言<span class="brand-sub"> / 项目</span></h1><button class="icon-btn add" data-action="create" aria-label="新建项目">${icon('plus')}</button></div><label class="search">${icon('search')}<input id="project-search" placeholder="搜索项目、笔记与待办" aria-label="搜索项目与笔记" value="${esc(search)}"></label>${searchFilterControls()}<div class="list-caption"><span id="search-caption">${searchActive()?'搜索结果':'我的项目'}</span><span id="search-total">${searchActive()?'':projects.length}</span></div></div><div class="project-list" id="project-list">${projectList()}</div><div class="side-bottom">${icon('lock')} 数据保存在本机</div></aside>`;}
function projectList(){if(searchActive())return globalSearchResults();const q=search.trim().toLowerCase();const matched=sortedProjects().filter(p=>p.name.toLowerCase().includes(q)||[...messages,...tasks].some(m=>m.projectId===p.id&&(m.text||m.name||'').toLowerCase().includes(q)));return matched.map(p=>{const latest=[...projectMessages(p.id),...projectTasks(p.id).map(t=>({...t,type:'task'}))].sort((a,b)=>b.created-a.created)[0];return `<button class="project ${p.id===activeId?'selected':''}" data-project="${p.id}">${avatar(p)}<div class="project-copy"><div class="project-line"><span class="project-name">${p.pinned?'<span class="pin">◆</span>':''}${esc(p.name)}</span><time>${shortTime(p.updated)}</time></div><div class="preview">${esc(preview(latest))}</div></div></button>`;}).join('')||'<div class="empty">没有找到相关记录</div>';}
function header(p){return `<header class="chat-head"><button class="icon-btn mobile-back" data-action="back" aria-label="返回项目列表">${icon('back')}</button>${avatar(p)}<div><h2>${esc(p.name)}</h2><div class="subtitle">${projectMessages().length} 条笔记</div></div><div class="head-right"><span class="local-pill"><span class="dot"></span>仅本机</span><button class="icon-btn" data-action="details" aria-label="项目详情">${icon('more')}</button></div></header>`;}
function taskbar(){const p=project(),list=projectTasks().filter(t=>!t.done);if(!p)return '';return `<section class="taskbar ${p.tasksOpen?'expanded':''}" aria-label="项目待办栏"><button class="taskbar-toggle" data-action="taskbar" aria-expanded="${!!p.tasksOpen}">${icon('tasks')}<span class="taskbar-count">待办 · 未完成 ${list.filter(t=>!t.done).length} 项</span><span class="taskbar-chevron">⌄</span></button><div class="taskbar-drawer"><div class="taskbar-inner"><div class="taskbar-list">${list.map(t=>taskRow(t,true)).join('')||'<div class="taskbar-empty">暂无未完成待办。点击输入框旁的「待办」添加。</div>'}</div><button class="taskbar-close" data-action="taskbar">⌃ 收起待办</button></div></div></section>`;}
function bubble(m){let content;if(['image','video','handwriting'].includes(m.type)){content=`<div class="bubble media-bubble">${m.type==='video'?`<video data-media="${m.id}" controls preload="metadata" playsinline></video>`:`<button class="image-open" ${m.type==='handwriting'?`data-ink="${m.id}"`:`data-image="${m.id}"`} aria-label="${m.type==='handwriting'?'打开手写笔记':'查看大图'}"><img data-media="${m.id}" alt="${esc(m.name)}" loading="lazy"></button>`}<div class="media-name">${esc(m.name)}${m.type==='handwriting'?` · ${m.pageCount} 页 <button class="text-link" data-ink="${m.id}">继续编辑</button>`:''}</div></div>`;}else content=`<div class="bubble ${m.type==='richtext'?'rich-content rich-bubble':''}">${m.type==='richtext'?cleanRich(m.html):esc(m.text)}</div>`;return `<article class="message" data-message="${m.id}"><div class="message-body">${m.edited?'<div class="edited-label">已编辑</div>':''}<button class="message-delete" data-menu="${m.id}" aria-label="消息操作">${icon('more')}</button>${content}</div><div class="avatar">我</div></article>`;}
function chat(){const p=project();if(!p)return '<div class="empty">新建一个项目，开始记录。<br><button class="primary" data-action="create">新建项目</button></div>';const all=projectMessages(),limit=limits.get(activeId)||60;let prev;const content=all.slice(-limit).map(m=>{const newDay=!prev||dayTime(prev.created)!==dayTime(m.created);const sep=!prev||newDay||m.created-prev.created>300000?`<div class="date-separator" data-timestamp="${m.created}">${newDay?dayTime(m.created)+' ':''}${clockTime(m.created)}</div>`:'';prev=m;return sep+bubble(m);}).join('');const text=draft().text;return `${header(p)}${taskbar()}<section class="messages" id="messages" aria-label="项目笔记">${all.length>limit?'<button class="load-older" data-action="older">加载更早的记录</button>':''}${content||'<div class="empty chat-empty">把想法，留在这里。<br><span>右滑回首页 · 左滑写手写笔记</span></div>'}</section><div class="compose-wrap"><form class="composer ${taskMode?'task-composer':''}" id="compose">${taskMode?'<div class="task-input-label">一次添加多项 · 回车新建下一项</div>':''}<textarea id="message-input" placeholder="${taskMode?'输入待办，回车继续下一项…':'写点什么，发给自己…'}" aria-label="${taskMode?'待办内容':'笔记内容'}" maxlength="50000" rows="2">${esc(text)}</textarea>${taskMode?'<div class="task-compose-options"><div id="task-input-preview">'+taskInputPreview(text)+'</div><button type="button" class="text-link" data-action="task-details">图片 / 截止日期</button></div>':''}<div class="composer-row"><div class="composer-tools"><button type="button" class="tool ${taskMode?'on':''}" data-action="task-mode" aria-pressed="${taskMode}">${icon('tasks')}<span>${taskMode?'待办模式':'待办'}</span></button><span class="input-hint">${taskMode?'保存到顶部，不发消息':'草稿自动保存'}</span></div><div class="send-tools"><button type="button" class="icon-btn attach-toggle" data-action="attachments" aria-label="添加附件">${icon('plus')}</button><button type="submit" class="send" id="send-button" ${text.trim()?'':'hidden'}>${taskMode?'保存待办':'发送'}</button></div></div></form>${attachmentOpen?`<div class="attachment-panel"><button data-pick="album">${icon('image')}<span>相册</span></button><button data-pick="camera">${icon('camera')}<span>拍照</span></button><button data-pick="video">${icon('video')}<span>视频</span></button><button data-action="handwrite">${icon('art')}<span>手写</span></button><button data-action="rich-note">${icon('note')}<span>图文笔记</span></button><button data-action="templates">${icon('note')}<span>模板</span></button></div>`:''}<div class="composer-note">${icon('lock')} 本地保存 · 长按消息可编辑或整理</div></div>`;}
function taskInputPreview(text){const lines=text.split('\n').map(s=>s.trim()).filter(Boolean);return lines.length?`<span class="task-entry-count">将保存 ${lines.length} 项</span>`:'';}
function tasksPage(){let filtered=tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));if(!orderSnapshot)orderSnapshot=[...filtered].sort(taskCompare).map(t=>t.id);const order=new Map(orderSnapshot.map((id,i)=>[id,i]));filtered.sort((a,b)=>(order.get(a.id)??1e9)-(order.get(b.id)??1e9)||taskCompare(a,b));return `<section class="page"><h2>待办事项</h2><p class="lead">截止三天内及逾期事项标红，按紧急程度排序。</p><div class="task-summary"><strong>${tasks.filter(t=>!t.done).length}</strong><span>项未完成</span>${icon('tasks')}</div><div class="filters">${[['open','未完成'],['done','已完成'],['all','全部']].map(([v,t])=>`<button data-filter="${v}" class="${taskFilter===v?'active':''}">${t}</button>`).join('')}</div>${filtered.map(t=>taskRow(t,false)).join('')||'<div class="empty">这里还没有待办。</div>'}</section>`;}
function settingsPage(){const native=!!window.ZiyanAndroid;return `<section class="page settings-page"><h2>我的空间</h2><p class="lead">不用登录，内容只保存在本机。</p><div class="setting-card identity-card"><img src="icon.svg" width="57" height="57" alt=""><div><h3>自言 <span class="count">${native?'APK '+esc(window.ZiyanAndroid.version()):'v0.7'}</span></h3><p>${projects.length} 个项目 · ${messages.length} 条笔记 · ${tasks.length} 项待办</p></div></div><div class="setting-card"><h3>完整备份与恢复</h3><p>包含全部项目、笔记、图片、视频、待办、手写原始笔迹、模板和草稿。可在另一浏览器或 APK 中导入，继续查看和编辑。</p><div class="settings-actions"><button class="primary" data-action="export">${icon('download')} 导出完整备份</button><button class="secondary" data-action="import">${icon('upload')} 导入备份</button></div><p class="fine-print">${native?'导出时选择系统文件保存位置。旧网页版 JSON 备份可以直接导入。':'HTML 是应用，JSON 备份是你的内容，请一起保留。'}导入会在确认后替换当前数据。</p></div><div class="setting-card"><h3>笔记模板</h3><p>题目与解答、公式推导、错题记录、实验记录，支持修改与自建。</p><button class="secondary" data-action="templates">管理模板</button></div><div class="setting-card"><h3>${native?'应用存储':'设备存储'}</h3><p id="storage-info">正在读取…</p>${native?'':'<button class="secondary" data-action="persist">申请保留本地数据</button>'}<p>${native?'内容保存在应用独立空间，清理浏览器不会影响这里的记录。卸载或清除本应用数据会删除记录，请定期导出备份。':'清理浏览器数据或卸载可能删除记录，请定期导出备份。'}</p></div><div class="setting-card"><h3>${native?'完全离线':'安卓使用'}</h3><p>${native?'界面内置在 APK 中，无需网络或本地服务器。不申请联网权限、不加载远程网页、不包含广告或统计服务。相册、拍照和文件保存通过系统界面操作。':'单文件 HTML 可离线打开；完整 PWA 通过 localhost 或 HTTPS 首次加载后，可添加到桌面。不同浏览器、不同地址的数据独立，迁移请使用备份。'}</p>${native?'':'<button class="secondary" data-action="install">安装说明</button>'}</div></section>`;}
function render(bottom=false){rememberDraft();renderVersion++;const route=`${page}/${inChat}/${activeId}`;const same=app.dataset.route===route;const oldPage=same?$('.page')?.scrollTop:0,oldMessages=same?$('#messages')?.scrollTop:undefined,oldTasks=same?$('.taskbar-list')?.scrollTop:0;app.className=page!=='projects'?'other-page':inChat?'in-chat':'';app.dataset.route=route;app.innerHTML=`${nav()}${sidebar()}<main class="main">${page==='projects'?chat():page==='tasks'?tasksPage():settingsPage()}</main>${page==='projects'&&inChat?'':nav(true)}`;if($('.page'))$('.page').scrollTop=oldPage||0;if($('.taskbar-list'))$('.taskbar-list').scrollTop=oldTasks||0;if(page==='projects'){const list=$('#messages');if(list){list.style.scrollBehavior='auto';list.scrollTop=bottom?list.scrollHeight:oldMessages??list.scrollHeight;list.dataset.pin=bottom?'1':'0';list.dataset.auto=bottom?'1':'0';for(const event of ['pointerdown','wheel','touchstart'])list.addEventListener(event,()=>{list.dataset.auto='0';},{passive:true});list.addEventListener('scroll',()=>{if(list.dataset.auto==='1')return;list.dataset.pin=list.scrollHeight-list.scrollTop-list.clientHeight<50?'1':'0';},{passive:true});}loadMedia(renderVersion).catch(failure);}else loadMedia(renderVersion).catch(failure);if(page==='settings')storageInfo().catch(failure);}
async function loadMedia(version){await Promise.all([...document.querySelectorAll('#app [data-media]')].map(async el=>{const mid=el.dataset.media;if(!mediaUrls.has(mid)){const record=await request('media','get',mid);if(!record){el.replaceWith(document.createTextNode('附件无法读取'));return;}mediaUrls.set(mid,URL.createObjectURL(record.blob));}if(version!==renderVersion)return;el.addEventListener('load',()=>{const list=$('#messages');if(list?.dataset.pin==='1')list.scrollTop=list.scrollHeight;},{once:true});el.src=mediaUrls.get(mid);}));}
function openProject(pid,mid){rememberDraft();$('#message-input')?.remove();activeId=pid;page='projects';inChat=true;taskMode=!!draft().taskMode;attachmentOpen=false;if(mid){const all=projectMessages(),at=all.findIndex(m=>m.id===mid);if(at>=0)limits.set(pid,Math.max(limits.get(pid)||60,all.length-at+5));}render(!mid);if(mid){const el=$(`[data-message="${mid}"]`);el?.scrollIntoView({block:'center'});el?.classList.add('highlight');}}
function showDialog(html){if(dialog.open)dialog.close();dialog.innerHTML=html;dialog.showModal();dialog.scrollTop=0;}
function closeDialog(){dialog.close();}
function searchActive(){return !!search.trim()||Object.values(searchFilters).some(Boolean);}
function typeOptions(value){return [['','全部类型'],['text','文字'],['richtext','图文'],['image','图片'],['video','视频'],['handwriting','手写'],['task','待办']].map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('');}
function searchFilterControls(){return `<details class="search-filters" ${Object.values(searchFilters).some(Boolean)?'open':''}><summary>筛选项目、类型与日期</summary><div class="search-filter-grid"><label>项目<select data-search-filter="project" aria-label="搜索项目筛选"><option value="">全部项目</option>${sortedProjects().map(p=>`<option value="${p.id}" ${p.id===searchFilters.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>内容类型<select data-search-filter="type" aria-label="搜索类型筛选">${typeOptions(searchFilters.type)}</select></label><label>开始日期<input type="date" data-search-filter="from" aria-label="搜索开始日期" value="${esc(searchFilters.from)}"></label><label>结束日期<input type="date" data-search-filter="to" aria-label="搜索结束日期" value="${esc(searchFilters.to)}"></label></div><button class="text-link" data-action="clear-search">清除搜索和筛选</button></details>`;}
function filterSearch(q,filters){const term=q.trim().toLowerCase();return [...messages,...tasks.map(t=>({...t,type:'task'}))].filter(m=>(!filters.project||m.projectId===filters.project)&&(!filters.type||m.type===filters.type)&&(!filters.from||m.created>=new Date(filters.from+'T00:00:00').getTime())&&(!filters.to||m.created<=dueEnd(filters.to))&&(!term||(m.text||m.name||'').toLowerCase().includes(term))).sort((a,b)=>b.created-a.created||a.id.localeCompare(b.id));}
function searchSnippet(m,q){const text=m.text||m.name||preview(m),term=q.trim(),at=term?text.toLowerCase().indexOf(term.toLowerCase()):-1,start=Math.max(0,at-30),end=Math.min(text.length,Math.max(start+140,at+term.length)),snippet=text.slice(start,end),offset=at-start;const content=at<0?esc(snippet):esc(snippet.slice(0,offset))+'<mark>'+esc(snippet.slice(offset,offset+term.length))+'</mark>'+esc(snippet.slice(offset+term.length));return (start?'…':'')+content+(end<text.length?'…':'');}
function searchResult(m,q){const kind=({text:'文字',richtext:'图文',image:'图片',video:'视频',handwriting:'手写',task:m.done?'已完成待办':'未完成待办'})[m.type];return `<button class="search-result" ${m.type==='task'?`data-search-task="${m.id}"`:`data-search-message="${m.id}" data-search-project="${m.projectId}"`}><span class="result-project">${esc(projects.find(p=>p.id===m.projectId)?.name)} · ${kind}</span><span class="result-snippet">${searchSnippet(m,q)}</span><span class="result-time">${dayTime(m.created)} ${clockTime(m.created)}</span></button>`;}
function globalSearchResults(){if(searchFilters.from&&searchFilters.to&&searchFilters.from>searchFilters.to)return '<div class="empty">开始日期不能晚于结束日期</div>';const found=filterSearch(search,searchFilters);const named=search.trim()&&!Object.values(searchFilters).some(Boolean)?sortedProjects().filter(p=>p.name.toLowerCase().includes(search.trim().toLowerCase())).map(p=>`<button class="search-result" data-project="${p.id}"><span class="result-project">项目</span>${esc(p.name)}</button>`).join(''):'';return named+found.map(m=>searchResult(m,search)).join('')||'<div class="empty">没有找到相关记录</div>';}
function updateGlobalSearch(){const list=$('#project-list');if(list)list.innerHTML=projectList();const caption=$('#search-caption');if(caption)caption.textContent=searchActive()?'搜索结果':'我的项目';const total=$('#search-total');if(total)total.textContent=searchActive()?'':projects.length;}
document.addEventListener('change',e=>{const key=e.target.dataset.searchFilter;if(key&&Object.hasOwn(searchFilters,key)){searchFilters[key]=e.target.value;updateGlobalSearch();}});
async function openTaskResult(tid){const t=tasks.find(t=>t.id===tid);if(!t)return;closeDialog();if(t.done){taskFilter='all';navigatePage('tasks');}else{const p=projects.find(p=>p.id===t.projectId);if(!p)return;await request('projects','put',{...p,tasksOpen:true});await refresh();openProject(p.id);}const row=$(`[data-task-row="${tid}"]`);row?.scrollIntoView({block:'center'});row?.classList.add('highlight');}
function forwardDialog(mid){const source=messages.find(m=>m.id===mid);if(!source)return;const targets=sortedProjects().filter(p=>p.id!==source.projectId);showDialog(`<h3>转发到其他项目</h3><p class="dialog-copy">选择接收项目。原记录保留，转发后可分别编辑。</p><div class="forward-targets">${targets.map(p=>`<button data-forward-project="${p.id}">${projectIcon(p.emoji)}<span>${esc(p.name)}</span></button>`).join('')||'<p class="dialog-copy">还没有其他项目，请先新建一个项目。</p>'}</div><div class="dialog-actions"><button class="secondary" data-close>取消</button></div>`);dialog.querySelectorAll('[data-forward-project]').forEach(button=>button.onclick=async()=>{dialog.querySelectorAll('[data-forward-project]').forEach(b=>b.disabled=true);try{await forwardMessage(mid,button.dataset.forwardProject);closeDialog();}catch(e){failure(e);dialog.querySelectorAll('[data-forward-project]').forEach(b=>b.disabled=false);}});}
async function forwardMessage(mid,pid){
 if(busy)throw new Error('正在保存，请稍后再试');
 const original=messages.find(m=>m.id===mid),target=projects.find(p=>p.id===pid);
 if(!original||!target||original.projectId===pid)throw new Error('原记录或目标项目已不存在');
 busy=true;
 try{
  const now=Date.now(),copy={...structuredClone(original),id:id(),projectId:pid,created:now};delete copy.edited;
  const media=[],remap=new Map(),refs=original.type==='richtext'?richMedia(original.html):['image','video','handwriting'].includes(original.type)?[mid]:[];
  for(const ref of refs){const data=await request('media','get',ref);if(!data?.blob)throw new Error('附件缺失，未转发');const next=ref===mid?copy.id:id();remap.set(ref,next);media.push({id:next,blob:data.blob});}
  if(original.type==='richtext'){const template=document.createElement('template');template.innerHTML=cleanRich(original.html);template.content.querySelectorAll('img[data-media]').forEach(img=>img.dataset.media=remap.get(img.dataset.media));copy.html=cleanRich(template.innerHTML);}
  let ink;if(original.type==='handwriting'){const saved=await request('ink','get',mid);if(!saved||saved.draft)throw new Error('原始笔迹缺失，未转发');ink={...structuredClone(saved),id:copy.id,projectId:pid,draft:false,sourceId:null,updated:now};delete ink.draftId;}
  await transaction(['messages','media','ink','projects'],tx=>{tx.objectStore('messages').put(copy);media.forEach(m=>tx.objectStore('media').put(m));if(ink)tx.objectStore('ink').put(ink);tx.objectStore('projects').put({...target,updated:now});});
  await refresh();render();toast(`已转发到「${target.name}」`);
 }finally{busy=false;}
}
function confirmAction(title,text,label,action){showDialog(`<h3>${esc(title)}</h3><p class="dialog-copy">${esc(text)}</p><div class="dialog-actions"><button class="secondary" data-close>取消</button><button class="danger" id="confirm-action">${esc(label)}</button></div>`);$('#confirm-action').onclick=async()=>{$('#confirm-action').disabled=true;try{await action();closeDialog();}catch(e){failure(e);if($('#confirm-action'))$('#confirm-action').disabled=false;}};}
function projectEditor(existing){let chosen=existing?.emoji||'🌱';showDialog(`<form id="project-form"><h3>${existing?'编辑项目':'新建项目'}</h3><label for="project-name">项目名称</label><input type="text" id="project-name" value="${esc(existing?.name||'')}" required maxlength="40"><label>项目图标</label><div class="emoji-options">${emojis.map(e=>`<button type="button" data-emoji="${e}" aria-label="${e}" class="${chosen===e?'selected':''}">${projectIcon(e)}</button>`).join('')}</div><div class="dialog-actions"><button class="secondary" type="button" data-close>取消</button><button class="primary" type="submit">保存</button></div></form>`);dialog.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{chosen=b.dataset.emoji;dialog.querySelectorAll('[data-emoji]').forEach(x=>x.classList.toggle('selected',x===b));});$('#project-form').onsubmit=async e=>{e.preventDefault();const name=$('#project-name').value.trim();if(!name)return;try{const now=Date.now(),p=existing?{...existing,name,emoji:chosen}:{id:id(),name,emoji:chosen,color:0,pinned:false,tasksOpen:false,created:now,updated:now};await request('projects','put',p);await refresh();closeDialog();openProject(p.id);}catch(e){failure(e);}};}
function details(){const p=project();if(!p)return;showDialog(`<div class="detail-title">${avatar(p)}<h3>${esc(p.name)}</h3></div><div class="menu-list"><button id="edit-project">编辑名称与图标</button><button id="pin-project">${p.pinned?'取消置顶':'置顶项目'}</button><button id="search-project">搜索笔记与待办</button><button id="view-attachments">图片、视频与手写</button><button id="delete-project">删除项目</button></div><div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>`);$('#edit-project').onclick=()=>projectEditor(p);$('#pin-project').onclick=async()=>{try{await request('projects','put',{...p,pinned:!p.pinned});await refresh();closeDialog();render();}catch(e){failure(e);}};$('#search-project').onclick=()=>searchProject(false);$('#view-attachments').onclick=()=>searchProject(true);$('#delete-project').onclick=()=>{closeDialog();deleteProject(p);};}
function searchProject(mediaOnly){const p=project();showDialog(`<h3>${mediaOnly?'附件与手写':'搜索本项目'}</h3><label class="search"><input id="inside-search" aria-label="搜索本项目" placeholder="输入关键词（可留空按条件查找）"></label><div class="search-filter-grid"><label>内容类型<select id="inside-type" aria-label="本项目搜索类型">${typeOptions('')}</select></label><label>开始日期<input id="inside-from" aria-label="本项目开始日期" type="date"></label><label>结束日期<input id="inside-to" aria-label="本项目结束日期" type="date"></label></div><div id="inside-results" class="inside-results"></div><div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>`);const update=()=>{const q=$('#inside-search').value,filters={project:p.id,type:$('#inside-type').value,from:$('#inside-from').value,to:$('#inside-to').value};if(filters.from&&filters.to&&filters.from>filters.to){$('#inside-results').innerHTML='<p class="dialog-copy">开始日期不能晚于结束日期</p>';return;}const found=filterSearch(q,filters).filter(m=>!mediaOnly||['image','video','handwriting','richtext'].includes(m.type));$('#inside-results').innerHTML=found.map(m=>searchResult(m,q)).join('')||'<p class="dialog-copy">没有相关记录</p>';};$('#inside-search').oninput=update;for(const key of ['inside-type','inside-from','inside-to'])$('#'+key).onchange=update;update();}
async function sendNote(){if(busy||!project())return;rememberDraft();const text=$('#message-input').value.trim();if(!text)return;busy=true;const p=project(),now=Date.now(),mode=taskMode;try{if(mode){const lines=text.split('\n').map(s=>s.trim().replace(/^□\s*/, '')).filter(Boolean);await transaction(['tasks','projects'],tx=>{lines.forEach((s,i)=>tx.objectStore('tasks').put({id:id(),projectId:p.id,text:s,done:false,created:now+i,dueDate:null,images:[]}));tx.objectStore('projects').put({...p,updated:now});});}else{await transaction(['messages','projects'],tx=>{tx.objectStore('messages').put({id:id(),projectId:p.id,type:'text',text,created:now});tx.objectStore('projects').put({...p,updated:now});});}clearComposerDraft(p.id);$('#message-input').value='';$('#message-input').remove();taskMode=false;draft(p.id).taskMode=false;persistDraft(p.id);attachmentOpen=false;await refresh();render(!mode);if(!mode)$('#message-input')?.focus();}finally{busy=false;}}
async function toggleTask(tid){const t=tasks.find(t=>t.id===tid);if(!t)return;const updated={...t,done:!t.done};await request('tasks','put',updated);tasks=tasks.map(x=>x.id===tid?updated:x);document.querySelectorAll(`[data-task-row="${tid}"]`).forEach(row=>{if(updated.done&&row.classList.contains('bar-task')){row.remove();return;}row.classList.toggle('done',updated.done);row.classList.toggle('urgent',!updated.done&&isUrgent(updated));const check=$('[data-toggle]',row);check.classList.toggle('checked',updated.done);check.innerHTML=updated.done?icon('check'):'';check.setAttribute('aria-pressed',updated.done);check.setAttribute('aria-label',updated.done?'标为未完成':'完成待办');});const count=$('.task-summary strong');if(count)count.textContent=tasks.filter(t=>!t.done).length;const bar=$('.taskbar-count');if(bar)bar.textContent=`待办 · 未完成 ${projectTasks().filter(t=>!t.done).length} 项`;$('#project-list').innerHTML=projectList();const list=$('.taskbar-list');if(list&&!$('.bar-task',list)&&!$('.taskbar-empty',list))list.innerHTML='<div class="taskbar-empty">暂无未完成待办。</div>';}
function taskMenu(tid,point){const t=tasks.find(t=>t.id===tid);if(!t)return;showMenu([{id:'edit-task',label:'编辑内容 / 图片 / 截止日期',run:()=>openEditor('task',t)},{id:'task-select',label:'选择部分文字',run:()=>selectText(t.text)},{id:'task-copy',label:'复制文字',run:()=>copyText(t.text)},{id:'task-delete',label:'删除待办',run:()=>confirmAction('删除待办？',t.text,'删除',async()=>{await request('tasks','delete',tid);await request('drafts','delete',`edit-task-${tid}`);await refresh();render();await collectUnusedMedia();})}],point,$(`[data-task-row="${tid}"]`));}
function messageMenu(mid,point){const m=messages.find(m=>m.id===mid);if(!m)return;const text=['text','richtext'].includes(m.type),items=[];if(text){items.push({id:'copy-message',label:'复制文字',run:()=>copyText(m.text)},{id:'edit-message',label:'编辑笔记',run:()=>openEditor('note',m)},{id:'select-message',label:'选择部分文字',run:()=>selectText(m.text)},{id:'convert-message',label:'转为待办',run:async()=>{await transaction(['messages','tasks','drafts'],tx=>{tx.objectStore('messages').delete(m.id);tx.objectStore('tasks').put({id:m.id,projectId:m.projectId,text:m.text,created:m.created,done:false,dueDate:null,images:m.type==='richtext'?richMedia(m.html):[]});tx.objectStore('drafts').delete(`edit-note-${m.id}`);});await refresh();render();toast('已转为待办');}});}else{if(m.type==='handwriting')items.push({id:'edit-handwriting',label:'继续编辑手写',run:()=>openHandwriting(m.id)});items.push({id:'save-media',label:m.type==='handwriting'?'保存预览图片':'保存附件',run:async()=>{const data=await request('media','get',m.id);const saved=await download(data.blob,m.type==='handwriting'?m.name+'.png':m.name);if(window.ZiyanFiles)toast(saved?'附件已保存':'已取消保存');}});}items.push({id:'forward-message',label:'转发到其他项目',run:()=>forwardDialog(m.id)},{id:'delete-message',label:'删除记录',run:()=>confirmAction('删除记录？','删除后无法撤销。','删除',async()=>{const ink=await request('ink','getAll');await transaction(['messages','media','ink','drafts'],tx=>{tx.objectStore('messages').delete(mid);tx.objectStore('media').delete(mid);tx.objectStore('drafts').delete(`edit-note-${mid}`);ink.filter(d=>d.id===mid||d.sourceId===mid).forEach(d=>tx.objectStore('ink').delete(d.id));});revokeMedia(mid);await refresh();render();await collectUnusedMedia();})});showMenu(items,point,$(`[data-message="${mid}"]`));}
function templatesDialog(){showDialog(`<h3>笔记模板</h3><div class="template-list">${templates.map(t=>`<div class="template-row"><button class="template-use" data-template-use="${t.id}">${esc(t.name)}</button><button class="text-link" data-template-edit="${t.id}">编辑</button></div>`).join('')}</div><div class="dialog-actions"><button class="secondary" id="new-template">新增模板</button><button class="secondary" data-close>关闭</button></div>`);dialog.querySelectorAll('[data-template-use]').forEach(b=>b.onclick=()=>{if(!project()||page!=='projects'){toast('请先进入一个项目，再使用模板');return;}rememberDraft();$('#message-input')?.remove();const t=templates.find(t=>t.id===b.dataset.templateUse);const combined=[draft().text,t.text].filter(Boolean).join('\n\n');if(combined.length>50000){toast('内容超过 5 万字，请先保存当前草稿');render();return;}draft().text=combined;taskMode=false;draft().taskMode=false;persistDraft();closeDialog();attachmentOpen=false;render();$('#message-input')?.focus();});dialog.querySelectorAll('[data-template-edit]').forEach(b=>b.onclick=()=>templateEditor(templates.find(t=>t.id===b.dataset.templateEdit)));$('#new-template').onclick=()=>templateEditor();}
function templateEditor(existing){showDialog(`<form id="template-form"><h3>${existing?'编辑模板':'新增模板'}</h3><label for="template-name">模板名称</label><input id="template-name" type="text" required maxlength="40" value="${esc(existing?.name||'')}"><label for="template-text">模板内容</label><textarea id="template-text" class="edit-text" required maxlength="50000">${esc(existing?.text||'')}</textarea><div class="dialog-actions">${existing?'<button type="button" id="delete-template" class="secondary">删除</button>':''}<button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存</button></div></form>`);$('#template-form').onsubmit=async e=>{e.preventDefault();const name=$('#template-name').value.trim(),text=$('#template-text').value;if(!name||!text.trim())return;try{await request('templates','put',{id:existing?.id||id(),name,text});await refresh();templatesDialog();}catch(e){failure(e);}};if(existing)$('#delete-template').onclick=()=>confirmAction('删除模板？',existing.name,'删除',async()=>{await request('templates','delete',existing.id);await refresh();});}
async function openHandwriting(mid){if(!project()||busy)return;rememberDraft();await pendingDraftWrites;page='ink';try{await inkEditor.open(activeId,mid);}catch(e){page='projects';throw e;}}
function pickMedia(mode){mediaProject=activeId;const input=$('#media-input');input.accept=mode==='video'?'video/*':'image/*';if(mode==='camera')input.setAttribute('capture','environment');else input.removeAttribute('capture');input.multiple=mode!=='camera';input.value='';input.click();}
async function addMedia(files,pid){if(busy)throw new Error('正在保存，请稍后再试');const p=projects.find(p=>p.id===pid),list=[...files];if(!p||!list.length)return;if(list.some(f=>!/^(image|video)\//.test(f.type)))throw new Error('请选择图片或视频');if(list.some(f=>f.size>200*1024*1024))throw new Error('单个附件上限 200MB');busy=true;try{const now=Date.now();await transaction(['messages','media','projects'],tx=>{list.forEach((f,i)=>{const mid=id();tx.objectStore('messages').put({id:mid,projectId:pid,type:f.type.startsWith('image/')?'image':'video',name:f.name,created:now+i});tx.objectStore('media').put({id:mid,blob:f});});tx.objectStore('projects').put({...p,updated:now+list.length});});await refresh();attachmentOpen=false;render(true);toast('附件已保存到本机');}finally{busy=false;}}
function revokeMedia(mid){if(mediaUrls.has(mid)){URL.revokeObjectURL(mediaUrls.get(mid));mediaUrls.delete(mid);}}
async function download(blob,name){if(window.ZiyanFiles)return await window.ZiyanFiles.save(blob,name);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);return true;}
function blobData(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
async function exportBackup(){if(busy)return toast('正在保存，请稍候');rememberDraft();await pendingDraftWrites;busy=true;toast('正在生成完整备份…');try{const data=await new Promise((resolve,reject)=>{const tx=db.transaction(STORES,'readonly'),out={};for(const s of STORES){const r=tx.objectStore(s).getAll();r.onsuccess=()=>out[s]=r.result;}tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error);});const media=[];const refs=allMediaRefs(data);for(const item of data.media.filter(m=>refs.has(m.id)))media.push({id:item.id,data:await blobData(item.blob)});const backup={app:'ziyan',version:3,exportedAt:new Date().toISOString(),...data,media};const saved=await download(new Blob([JSON.stringify(backup)],{type:'application/json'}),`自言完整备份-${new Date().toISOString().slice(0,10)}.json`);toast(saved?(window.ZiyanFiles?'完整备份已保存':'完整备份已生成'):'已取消导出');}finally{busy=false;}}
function validateLegacyBackup(data){
 const invalid=()=>{throw new Error('备份格式不完整或已损坏，当前数据未改变');};
 const validId=v=>typeof v==='string'&&/^[\w-]{1,150}$/.test(v);
 const validTime=v=>Number.isFinite(v)&&Math.abs(v)<8e15;
 if(data?.app!=='ziyan'||![1,2].includes(data.version))invalid();
 for(const s of ['projects','messages','media'])if(!Array.isArray(data[s]))invalid();
 const out={};for(const s of STORES)out[s]=data.version===1&&!['projects','messages','media'].includes(s)?[]:data[s];
 for(const s of STORES)if(!Array.isArray(out[s]))invalid();
 const pids=new Set();out.projects=out.projects.map(p=>{if(!validId(p?.id)||pids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>40||typeof p.emoji!=='string'||p.emoji.length>16||!validTime(p.created)||!validTime(p.updated))invalid();pids.add(p.id);return {id:p.id,name:p.name,emoji:p.emoji,color:0,pinned:!!p.pinned,tasksOpen:!!p.tasksOpen,created:p.created,updated:p.updated};});
 const used=new Set();const validRecord=m=>{if(!validId(m?.id)||used.has(m.id)||!pids.has(m.projectId)||!validTime(m.created))invalid();used.add(m.id);};
 const legacy=[];out.messages=out.messages.map(m=>{validRecord(m);if(!['text','task','image','video','handwriting'].includes(m.type))invalid();const c={id:m.id,projectId:m.projectId,type:m.type,created:m.created};if(validTime(m.edited))c.edited=m.edited;if(['text','task'].includes(m.type)){if(typeof m.text!=='string'||!m.text.trim()||m.text.length>50000)invalid();c.text=m.text;if(m.type==='task'){legacy.push({...c,done:!!m.done});return null;}}else{if(typeof m.name!=='string'||m.name.length>1000)invalid();c.name=m.name;if(m.type==='handwriting'){if(!Number.isInteger(m.pageCount)||m.pageCount<1||m.pageCount>200)invalid();c.pageCount=m.pageCount;}}return c;}).filter(Boolean);
 out.tasks=out.tasks.map(t=>{validRecord(t);if(typeof t.text!=='string'||!t.text.trim()||t.text.length>50000)invalid();return {id:t.id,projectId:t.projectId,text:t.text,done:!!t.done,created:t.created};}).concat(legacy.map(({type,...t})=>t));
 if(legacy.length)out.projects.forEach(p=>{if(legacy.some(t=>t.projectId===p.id))p.tasksOpen=true;});
 const messageMap=new Map(out.messages.map(m=>[m.id,m])),mediaIds=new Set();out.media=out.media.map(item=>{const m=messageMap.get(item?.id);if(!m||!['image','video','handwriting'].includes(m.type)||mediaIds.has(item.id)||typeof item.data!=='string')invalid();const match=/^data:((?:image|video)\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/]*={0,2})$/.exec(item.data);if(!match||!match[1].startsWith(m.type==='video'?'video/':'image/'))invalid();let binary;try{binary=atob(match[2]);}catch{invalid();}if(binary.length>200*1024*1024)invalid();mediaIds.add(item.id);return {id:item.id,blob:new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:match[1]})};});
 if(out.messages.some(m=>['image','video','handwriting'].includes(m.type)&&!mediaIds.has(m.id)))invalid();
 const ids=new Set();out.ink=out.ink.map(d=>{if(!validId(d?.id)||ids.has(d.id)||!pids.has(d.projectId)||typeof d.title!=='string'||d.title.length>100||!Array.isArray(d.pages)||!d.pages.length||d.pages.length>200)invalid();ids.add(d.id);if(d.draft){if(d.sourceId&&(messageMap.get(d.sourceId)?.type!=='handwriting'||messageMap.get(d.sourceId)?.projectId!==d.projectId))invalid();}else if(messageMap.get(d.id)?.type!=='handwriting'||messageMap.get(d.id).projectId!==d.projectId)invalid();const pages=d.pages.map(pg=>{if(!['blank','grid','lines'].includes(pg?.paper)||!Array.isArray(pg.strokes)||pg.strokes.length>50000)invalid();return {paper:pg.paper,strokes:pg.strokes.map(s=>{if(!validId(s?.id)||!['#ededed','#3cb474'].includes(s.color)||!Number.isFinite(s.width)||s.width<.5||s.width>30||!Array.isArray(s.points)||!s.points.length||s.points.length>200000)invalid();return {id:s.id,color:s.color,width:s.width,points:s.points.map(pt=>{if(!Array.isArray(pt)||pt.length!==3||!pt.every(Number.isFinite)||Math.abs(pt[0])>100000||Math.abs(pt[1])>100000||pt[2]<0||pt[2]>1)invalid();return pt;})};})};});return {id:d.id,projectId:d.projectId,title:d.title,pages,draft:!!d.draft,sourceId:d.sourceId||null,pageIndex:Math.min(Math.max(0,Math.floor(d.pageIndex)||0),pages.length-1),updated:validTime(d.updated)?d.updated:Date.now()};});
 if(out.messages.some(m=>m.type==='handwriting'&&(!out.ink.some(d=>d.id===m.id&&!d.draft)||out.ink.find(d=>d.id===m.id).pages.length!==m.pageCount)))invalid();
 const draftIds=new Set();out.drafts=out.drafts.map(d=>{if(!pids.has(d?.id)||draftIds.has(d.id)||typeof d.text!=='string'||typeof d.taskText!=='string'||d.text.length>50000||d.taskText.length>50000)invalid();draftIds.add(d.id);return {id:d.id,text:d.text,taskText:d.taskText,taskMode:!!d.taskMode};});
 const tids=new Set();out.templates=out.templates.map(t=>{if(!validId(t?.id)||tids.has(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>40||typeof t.text!=='string'||!t.text.trim()||t.text.length>50000)invalid();tids.add(t.id);return {id:t.id,name:t.name,text:t.text};});
 if(data.version===1)out.templates=structuredClone(DEFAULT_TEMPLATES);
 return out;
}
async function readBackup(file){if(!file)return;if(busy)return toast('正在保存，请稍后再恢复');if(file.size>512*1024*1024)throw new Error('初版备份导入上限 512MB');let data;try{data=validateBackup(JSON.parse(await file.text()));}catch(e){throw new Error(e instanceof SyntaxError?'无法识别备份，当前数据未改变':e.message);}confirmAction('恢复完整备份？',`${data.projects.length} 个项目、${data.messages.length} 条笔记、${data.tasks.length} 项待办、${data.media.length} 个附件。将替换当前数据。`,'替换并恢复',async()=>{if(busy)throw new Error('正在保存，请稍后重试');rememberDraft();await pendingDraftWrites;busy=true;try{await transaction(STORES,tx=>{for(const s of STORES){const store=tx.objectStore(s);store.clear();data[s].forEach(item=>store.put(item));}});[...mediaUrls.keys()].forEach(revokeMedia);drafts.clear();data.drafts.forEach(d=>drafts.set(d.id,d));$('#message-input')?.remove();activeId=undefined;await refresh();taskMode=!!draft().taskMode;page='projects';inChat=false;search='';render();toast('备份已恢复');}finally{busy=false;}});}
async function storageInfo(){const el=$('#storage-info');if(!el)return;if(!navigator.storage?.estimate){el.textContent='浏览器不支持读取存储占用';return;}const [s,p]=await Promise.all([navigator.storage.estimate(),navigator.storage.persisted?.()]);if(el.isConnected)el.textContent=`约占用 ${((s.usage||0)/1048576).toFixed(1)} MB · ${p?'已获持久存储权限':'请定期导出备份'}`;}
function installHelp(){showDialog('<h3>安卓使用</h3><p class="dialog-copy">通过本机 localhost 或 HTTPS 打开，首次加载完成后，在 Chrome 菜单选择「添加到主屏幕」或「安装应用」。单文件 HTML 不需要安装，内容仍保存在当前浏览器；换浏览器请使用完整备份迁移。</p><div class="dialog-actions"><button class="primary" data-close>知道了</button></div>');}
async function toggleTaskbar(){const p=project();if(!p)return;p.tasksOpen=!p.tasksOpen;const node=$('.taskbar');node.classList.toggle('expanded',p.tasksOpen);$('.taskbar-toggle').setAttribute('aria-expanded',p.tasksOpen);await request('projects','put',p);}

function dueEnd(date){if(!date)return null;const [y,m,d]=date.split('-').map(Number);return new Date(y,m-1,d,23,59,59,999).getTime();}
function validDue(date){if(date==null||date==='')return true;if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;const [y,m,d]=date.split('-').map(Number),dt=new Date(y,m-1,d);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d;}
function daysLeft(t){if(!t.dueDate)return Infinity;const [y,m,d]=t.dueDate.split('-').map(Number),now=new Date();return Math.round((Date.UTC(y,m-1,d)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);}
function isUrgent(t){return !t.done&&!!t.dueDate&&daysLeft(t)<=3;}
function taskCompare(a,b){return Number(a.done)-Number(b.done)||((dueEnd(a.dueDate)??Infinity)-(dueEnd(b.dueDate)??Infinity))||b.created-a.created;}
function taskMetadata(t){const days=daysLeft(t),due=t.dueDate?(days<0?`逾期 ${-days} 天 · ${t.dueDate}`:days===0?'今天截止':days===1?'明天截止':`${t.dueDate} 截止`):'未设置截止日期';return `<small class="task-created">创建 ${dayTime(t.created)} ${clockTime(t.created)}</small><small class="task-due">${esc(due)}</small>`;}
function taskRow(t,bar){return `<${bar?'div':'article'} class="${bar?'bar-task':'task-card'} ${t.done?'done':''} ${!bar&&isUrgent(t)?'urgent':''}" data-task-row="${t.id}"><button class="check ${t.done?'checked':''}" data-toggle="${t.id}" aria-pressed="${t.done}" aria-label="${t.done?'标为未完成':'完成待办'}">${t.done?icon('check'):''}</button><div class="content"><button class="task-text" data-inline-task="${t.id}" aria-label="编辑待办文字">${esc(t.text||'图片待办')}</button><div class="task-meta">${taskMetadata(t)}</div>${(t.images||[]).length?`<div class="task-photos">${t.images.map(mid=>`<button data-task-photo="${mid}" aria-label="查看待办图片"><img data-media="${mid}" alt="待办图片" loading="lazy"></button>`).join('')}</div>`:''}${bar?'':`<small>${esc(projects.find(p=>p.id===t.projectId)?.name)}</small>`}</div>${bar?'':`<button class="text-link" data-task-project="${t.projectId}">查看项目</button>`}<button class="icon-btn" data-task-menu="${t.id}" aria-label="待办操作">${icon('more')}</button></${bar?'div':'article'}>`;}
let taskWrites=Promise.resolve();
function editTaskInline(tid){const t=tasks.find(t=>t.id===tid),button=$(`[data-inline-task="${tid}"]`);if(!t||!button)return;const wrap=document.createElement('div');wrap.className='inline-task-edit';wrap.innerHTML=`<textarea aria-label="编辑待办文字" maxlength="50000">${esc(t.text)}</textarea><button class="text-link">保存</button>`;button.replaceWith(wrap);const input=$('textarea',wrap);let done=false;const commit=()=>{if(done)return;const text=input.value.trim();if(!text&&!t.images?.length){toast('待办内容不能为空');input.focus();return;}done=true;taskWrites=taskWrites.catch(()=>{}).then(async()=>{const original=tasks.find(t=>t.id===tid);if(!original)return;const updated={...original,text};await request('tasks','put',updated);tasks=tasks.map(t=>t.id===tid?updated:t);document.querySelectorAll(`[data-task-row="${tid}"] .task-text`).forEach(el=>el.textContent=text||'图片待办');const b=document.createElement('button');b.className='task-text';b.dataset.inlineTask=tid;b.setAttribute('aria-label','编辑待办文字');b.textContent=text||'图片待办';wrap.replaceWith(b);});taskWrites.catch(e=>{done=false;failure(e);});};$('button',wrap).onpointerdown=e=>e.preventDefault();$('button',wrap).onclick=commit;input.onblur=commit;input.onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();commit();}if(e.key==='Escape'){done=true;wrap.replaceWith(button);}};input.focus();input.setSelectionRange(input.value.length,input.value.length);}
async function openEditor(kind,source){editorReturn={page,inChat,activeId};rememberDraft();await pendingDraftWrites;await noteEditor.open(source?.projectId||activeId,kind,source);}
async function newTaskDetails(){rememberDraft();await pendingDraftWrites;const key=`edit-task-${activeId}`;const saved=await request('drafts','get',key);if(!saved&&draft().text)await request('drafts','put',{id:key,kind:'task',projectId:activeId,sourceId:null,text:draft().text,html:'',dueDate:null,images:[],updated:Date.now()});await openEditor('task');}
function allMediaRefs(data){const refs=new Set();for(const m of data.messages||[]){if(['image','video','handwriting'].includes(m.type))refs.add(m.id);if(m.type==='richtext')richMedia(m.html).forEach(i=>refs.add(i));}for(const t of data.tasks||[])(t.images||[]).forEach(i=>refs.add(i));for(const d of data.drafts||[]){(d.images||[]).forEach(i=>refs.add(i));if(d.kind==='note')richMedia(d.html).forEach(i=>refs.add(i));}return refs;}
async function collectUnusedMedia(){const [ms,ts,ds,files]=await Promise.all(['messages','tasks','drafts','media'].map(s=>request(s,'getAll')));const refs=allMediaRefs({messages:ms,tasks:ts,drafts:ds});const unused=files.filter(m=>!refs.has(m.id));if(unused.length)await transaction(['media'],tx=>unused.forEach(m=>tx.objectStore('media').delete(m.id)));unused.forEach(m=>revokeMedia(m.id));}
function closeMenu(){menuRoot?.remove();menuRoot=null;menuAnchor?.classList.remove('context-active');menuAnchor=null;}
function showMenu(items,point,anchor){closeMenu();menuAnchor=anchor;anchor?.classList.add('context-active');menuRoot=document.createElement('div');menuRoot.className='context-layer';menuRoot.innerHTML=`<div class="context-menu" role="menu">${items.map(item=>`<button id="${item.id}" role="menuitem">${esc(item.label)}</button>`).join('')}</div>`;document.body.append(menuRoot);const menu=$('.context-menu',menuRoot);const r=anchor?.getBoundingClientRect();const at=point||menuPoint||{x:r?(r.left+r.right)/2:innerWidth/2,y:r?r.top:innerHeight/2};menu.style.left=Math.max(10,Math.min(at.x,innerWidth-menu.offsetWidth-10))+'px';menu.style.top=Math.max(10,Math.min(at.y,innerHeight-menu.offsetHeight-10))+'px';menuRoot.onpointerdown=e=>{if(e.target===menuRoot)closeMenu();};items.forEach(item=>$('#'+item.id,menu).onclick=async e=>{e.stopPropagation();closeMenu();try{await item.run();}catch(error){failure(error);}});menuPoint=null;}
async function copyText(text){if(window.ZiyanAndroid){if(!window.ZiyanAndroid.copyText(text))throw new Error('复制失败');}else await navigator.clipboard.writeText(text);toast('已复制');}
function selectText(text){selecting=true;const root=document.createElement('section');root.className='selection-view';root.innerHTML=`<header class="editor-head"><button class="icon-btn" id="selection-back" aria-label="返回聊天">‹</button><h2>选择文字</h2><button class="send" id="selection-copy">复制所选</button></header><p class="selection-help">长按文字，拖动选择手柄选取需要的部分。</p><textarea id="selection-text" readonly aria-label="选择部分文字">${esc(text)}</textarea>`;document.body.append(root);app.inert=true;$('#selection-back').onclick=closeSelection;$('#selection-copy').onclick=async()=>{const input=$('#selection-text');const selected=input.value.slice(input.selectionStart,input.selectionEnd);if(!selected)return toast('请先选择需要复制的文字');try{await copyText(selected);}catch(e){failure(e);}};}
function closeSelection(){document.querySelector('.selection-view')?.remove();selecting=false;app.inert=false;}
function projectMenu(pid,point){const p=projects.find(p=>p.id===pid);if(!p)return;showMenu([{id:'project-pin',label:p.pinned?'取消置顶':'置顶项目',run:async()=>{await request('projects','put',{...p,pinned:!p.pinned});await refresh();render();}},{id:'project-edit',label:'编辑项目',run:()=>projectEditor(p)},{id:'project-delete',label:'删除项目',run:()=>deleteProject(p)}],point,$(`[data-project="${pid}"]`));}
function deleteProject(p){confirmAction('删除项目？','全部笔记、待办、草稿和附件将被删除，无法撤销。','删除',async()=>{rememberDraft();await pendingDraftWrites;const [inks,ds]=await Promise.all([request('ink','getAll'),request('drafts','getAll')]);await transaction(['projects','messages','tasks','drafts','ink'],tx=>{tx.objectStore('projects').delete(p.id);projectMessages(p.id).forEach(m=>tx.objectStore('messages').delete(m.id));projectTasks(p.id).forEach(t=>tx.objectStore('tasks').delete(t.id));inks.filter(d=>d.projectId===p.id).forEach(d=>tx.objectStore('ink').delete(d.id));ds.filter(d=>d.id===p.id||d.projectId===p.id).forEach(d=>{tx.objectStore('drafts').delete(d.id);drafts.delete(d.id);});});$('#message-input')?.remove();await refresh();inChat=false;render();await collectUnusedMedia();});}
function validateBackup(data){
 if(![1,2,3].includes(data?.version))throw new Error('不支持这个备份版本');
 if(data.version!==3){const out=validateLegacyBackup(data);out.tasks.forEach(t=>{t.images=[];t.dueDate=null;});return out;}
 const invalid=()=>{throw new Error('备份格式不完整或已损坏，当前数据未改变');};
 const validId=v=>typeof v==='string'&&/^[\w-]{1,150}$/.test(v);
 if(!Array.isArray(data.messages)||!Array.isArray(data.tasks)||!Array.isArray(data.drafts)||!Array.isArray(data.media))invalid();
 const extras=new Map(),rawMessages=data.messages.map(m=>{if(m?.type!=='richtext')return m;if(typeof m.html!=='string'||m.html.length>1000000)invalid();const html=cleanRich(m.html),text=richText(html);if(text.length>50000||(!text&&!richMedia(html).length))invalid();extras.set(m.id,html);return {...m,type:'text',text:text||'[图片笔记]'};});
 const inlineDrafts=data.drafts.filter(d=>d?.kind==='note'||d?.kind==='task'),baseDrafts=data.drafts.filter(d=>!d?.kind).map(d=>({...d,taskText:typeof d.taskText==='string'?d.taskText:''}));
 const baseMediaIds=new Set(rawMessages.filter(m=>['image','video','handwriting'].includes(m.type)).map(m=>m.id));
 const out=validateLegacyBackup({...data,version:2,messages:rawMessages,tasks:data.tasks.map(t=>({...t,text:t.text||'[图片待办]'})),drafts:baseDrafts,media:data.media.filter(m=>baseMediaIds.has(m?.id))});
 out.messages=out.messages.map(m=>extras.has(m.id)?{...m,type:'richtext',html:extras.get(m.id),text:richText(extras.get(m.id))}:m);
 const pids=new Set(out.projects.map(p=>p.id)),recordMap=new Map([...out.messages,...out.tasks].map(m=>[m.id,m]));
 const imageList=value=>{if(value==null)return [];if(!Array.isArray(value)||value.length>100||value.some(i=>!validId(i))||new Set(value).size!==value.length)invalid();return value;};
 out.tasks=out.tasks.map(t=>{const raw=data.tasks.find(x=>x.id===t.id)||data.messages.find(x=>x.id===t.id);if(!raw||!validDue(raw.dueDate))invalid();if(typeof raw.text!=='string'||(!raw.text.trim()&&!raw.images?.length))invalid();return {...t,text:raw.text,dueDate:raw.dueDate||null,images:imageList(raw.images)};});
 const draftIds=new Set(out.drafts.map(d=>d.id));out.drafts=out.drafts.map(d=>({...d,unified:!!data.drafts.find(x=>x.id===d.id)?.unified}));
 for(const d of inlineDrafts){if(!validId(d.id)||draftIds.has(d.id)||!pids.has(d.projectId)||typeof d.text!=='string'||d.text.length>50000||typeof d.html!=='string'||d.html.length>1000000||!validDue(d.dueDate))invalid();if(d.sourceId){const src=recordMap.get(d.sourceId);if(!src||src.projectId!==d.projectId||(d.kind==='task'?!out.tasks.some(t=>t.id===src.id):!['text','richtext'].includes(src.type)))invalid();}draftIds.add(d.id);out.drafts.push({id:d.id,projectId:d.projectId,sourceId:d.sourceId||null,kind:d.kind,text:d.text,html:cleanRich(d.html),images:imageList(d.images),dueDate:d.dueDate||null,updated:Number.isFinite(d.updated)?d.updated:Date.now()});}
 const refs=allMediaRefs(out),seen=new Set(out.media.map(m=>m.id));
 for(const item of data.media){if(baseMediaIds.has(item?.id))continue;if(!validId(item?.id)||seen.has(item.id)||!refs.has(item.id)||typeof item.data!=='string')invalid();const match=/^data:(image\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/]*={0,2})$/.exec(item.data);if(!match)invalid();let raw;try{raw=atob(match[2]);}catch{invalid();}if(raw.length>200*1024*1024)invalid();out.media.push({id:item.id,blob:new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:match[1]})});seen.add(item.id);}
 if([...refs].some(mid=>!seen.has(mid)))invalid();
 const imageIds=new Set(out.media.filter(m=>m.blob.type.startsWith('image/')).map(m=>m.id));
 for(const t of out.tasks)if(t.images.some(mid=>!imageIds.has(mid)))invalid();
 for(const m of out.messages.filter(m=>m.type==='richtext'))if(richMedia(m.html).some(mid=>!imageIds.has(mid)))invalid();
 for(const d of inlineDrafts)if([...imageList(d.images),...richMedia(d.html)].some(mid=>!imageIds.has(mid)))invalid();
 return out;
}
function loadOlder(){const list=$('#messages'),top=list.getBoundingClientRect().top;const anchor=[...list.querySelectorAll('[data-message]')].find(el=>el.getBoundingClientRect().bottom>=top);const offset=anchor?anchor.getBoundingClientRect().top-top:0;const mid=anchor?.dataset.message;limits.set(activeId,(limits.get(activeId)||60)+60);render();const next=mid?$(`[data-message="${mid}"]`):null;if(next)$('#messages').scrollTop+=next.getBoundingClientRect().top-$('#messages').getBoundingClientRect().top-offset;}
function prepareSwipe(target,direction){const preview=document.createElement('div');preview.className='swipe-preview';let html;if(target==='home')html=sidebar();else if(target==='ink')html='<div class="swipe-ink-placeholder">手写笔记</div>';else{const previous=page;page=target;try{html=target==='projects'?sidebar():target==='tasks'?tasksPage():settingsPage();}finally{page=previous;}}preview.innerHTML=`<div class="preview-layout">${html}</div>`;if(gestureBounds)Object.assign(preview.style,{inset:'auto',left:gestureBounds.x+'px',top:gestureBounds.y+'px',width:gestureBounds.width+'px',height:gestureBounds.height+'px'});preview.inert=true;preview.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));document.body.append(preview);preview.style.transform=`translateX(${direction*innerWidth}px)`;return preview;}
function swipeTarget(dx){if(page==='projects'&&inChat)return dx>0?'home':'ink';const index=['projects','tasks','settings'].indexOf(page);return ['projects','tasks','settings'][index+(dx<0?1:-1)]||null;}
function clearSwipe(){gestureView?.remove();gestureView=null;app.classList.remove('swiping');if(gestureSurface){gestureSurface.style.transition='';gestureSurface.style.transform='';}gestureSurface=null;gestureBounds=null;}
async function completeSwipe(s,dx){const target=swipeTarget(dx),go=target&&(Math.abs(dx)>innerWidth*.25||(Math.abs(dx)>60&&Math.abs(dx)/(Date.now()-s.time)>.45));navigating=true;suppressClickUntil=Date.now()+400;suppressedClickTarget=null;const sign=dx<0?-1:1;gestureSurface.style.transition='transform 180ms ease-out';if(gestureView)gestureView.style.transition='transform 180ms ease-out';gestureSurface.style.transform=`translateX(${go?sign*innerWidth:0}px)`;if(gestureView)gestureView.style.transform=`translateX(${go?0:-sign*innerWidth}px)`;await new Promise(r=>setTimeout(r,185));clearSwipe();if(go){if(target==='home'){inChat=false;render();}else if(target==='ink')await openHandwriting();else navigatePage(target);}navigating=false;}
function navigatePage(target){rememberDraft();closeMenu();page=target;inChat=false;orderSnapshot=null;render();}
function showImage(mid,name='图片'){if(!mediaUrls.has(mid))return toast('图片正在加载');showDialog(`<img class="full-image" src="${mediaUrls.get(mid)}" alt="${esc(name)}"><div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>`);}
document.addEventListener('click',async e=>{if(e.target.closest('.note-editor,.selection-view,.context-menu,.ink-editor'))return;if(Date.now()<suppressClickUntil&&(!suppressedClickTarget||suppressedClickTarget.contains(e.target))){suppressClickUntil=0;suppressedClickTarget=null;e.preventDefault();return;}if(e.target.matches('.rich-bubble img[data-media]'))return showImage(e.target.dataset.media,e.target.alt);const b=e.target.closest('button');if(!b)return;try{if(b.dataset.searchMessage){closeDialog();return openProject(b.dataset.searchProject,b.dataset.searchMessage);}if(b.dataset.searchTask)return await openTaskResult(b.dataset.searchTask);if(b.hasAttribute('data-close'))return closeDialog();if(b.dataset.page)return navigatePage(b.dataset.page);if(b.dataset.project)return openProject(b.dataset.project);if(b.dataset.toggle){await taskWrites;taskOperations=taskOperations.catch(()=>{}).then(()=>toggleTask(b.dataset.toggle));return await taskOperations;}if(b.dataset.inlineTask)return editTaskInline(b.dataset.inlineTask);if(b.dataset.taskMenu)return taskMenu(b.dataset.taskMenu);if(b.dataset.menu)return messageMenu(b.dataset.menu);if(b.dataset.taskPhoto)return showImage(b.dataset.taskPhoto,'待办图片');if(b.dataset.taskProject){const p=projects.find(p=>p.id===b.dataset.taskProject);await request('projects','put',{...p,tasksOpen:true});await refresh();return openProject(p.id);}if(b.dataset.filter){taskFilter=b.dataset.filter;orderSnapshot=null;render();return;}if(b.dataset.pick)return pickMedia(b.dataset.pick);if(b.dataset.ink)return await openHandwriting(b.dataset.ink);if(b.dataset.image){const m=messages.find(m=>m.id===b.dataset.image);return showImage(m.id,m.name);}switch(b.dataset.action){case 'clear-search':search='';Object.keys(searchFilters).forEach(k=>searchFilters[k]='');$('#project-search').value='';document.querySelectorAll('[data-search-filter]').forEach(el=>el.value='');updateGlobalSearch();return;case 'create':return projectEditor();case 'back':inChat=false;render();return;case 'details':return details();case 'taskbar':return await toggleTaskbar();case 'task-mode':rememberDraft();$('#message-input')?.remove();taskMode=!taskMode;draft().taskMode=taskMode;persistDraft();render();$('#message-input')?.focus();return;case 'attachments':attachmentOpen=!attachmentOpen;render();return;case 'older':return loadOlder();case 'handwrite':return await openHandwriting();case 'rich-note':return await openEditor('note');case 'task-details':return await newTaskDetails();case 'templates':return templatesDialog();case 'export':return await exportBackup();case 'import':$('#backup-input').value='';$('#backup-input').click();return;case 'install':return installHelp();case 'persist':toast(await navigator.storage?.persist?.()?'已获持久存储权限':'请定期备份');return storageInfo();}}catch(error){failure(error);}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){search=e.target.value;updateGlobalSearch();}if(e.target.id==='message-input'){draft().text=e.target.value;draft().taskMode=taskMode;persistDraft();$('#send-button').hidden=!e.target.value.trim();if(taskMode)$('#task-input-preview').innerHTML=taskInputPreview(e.target.value);}});
document.addEventListener('submit',e=>{if(e.target.id==='compose'){e.preventDefault();sendNote().catch(failure);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuRoot){closeMenu();return;}if(e.target.id==='message-input'&&e.key==='Enter'&&!e.isComposing&&(e.ctrlKey||e.metaKey)){e.preventDefault();sendNote().catch(failure);}});
function longPressTarget(target){const projectEl=target.closest('[data-project]'),messageEl=target.closest('[data-message]'),taskEl=target.closest('[data-task-row]');if(target.closest('input,textarea,[contenteditable],.note-editor,.ink-editor,.selection-view'))return null;return projectEl?{type:'project',id:projectEl.dataset.project}:messageEl?{type:'message',id:messageEl.dataset.message}:taskEl?{type:'task',id:taskEl.dataset.taskRow}:null;}
function openLongPress(target,point){if(target.type==='project')projectMenu(target.id,point);if(target.type==='message')messageMenu(target.id,point);if(target.type==='task')taskMenu(target.id,point);}
document.addEventListener('contextmenu',e=>{const target=longPressTarget(e.target);if(target){e.preventDefault();clearTimeout(longPressTimer);openLongPress(target,{x:e.clientX,y:e.clientY});}});
document.addEventListener('pointerdown',e=>{if(!app.contains(e.target)||e.pointerType==='mouse'||dialog.open||menuRoot||selecting||document.querySelector('.note-editor,.ink-editor')||navigating)return;const target=longPressTarget(e.target);if(target&&!e.target.closest('[data-toggle],input,textarea')){pressStart={x:e.clientX,y:e.clientY};longPressTimer=setTimeout(()=>{swipeStart=null;clearSwipe();suppressClickUntil=Date.now()+650;suppressedClickTarget=e.target.closest('[data-project],[data-message],[data-task-row]');openLongPress(target,{x:e.clientX,y:e.clientY});navigator.vibrate?.(20);},550);}const excluded=e.target.closest('input,textarea,select,[contenteditable],video,audio,canvas,.composer,.attachment-panel,.taskbar,.mobile-nav,.rail,.head-right');swipeStart=excluded?null:{x:e.clientX,y:e.clientY,time:Date.now(),pointerId:e.pointerId,axis:null,target:null};});
document.addEventListener('pointermove',e=>{if(pressStart&&Math.hypot(e.clientX-pressStart.x,e.clientY-pressStart.y)>10)clearTimeout(longPressTimer);const s=swipeStart;if(!s||s.pointerId!==e.pointerId)return;const dx=e.clientX-s.x,dy=e.clientY-s.y;if(!s.axis&&Math.hypot(dx,dy)>10)s.axis=Math.abs(dx)>Math.abs(dy)*1.5?'x':'y';if(s.axis!=='x')return;if(!gestureSurface){gestureSurface=innerWidth<=760?(page==='projects'&&!inChat?$('.sidebar',app):$('.main',app)):app;gestureBounds=gestureSurface.getBoundingClientRect();}app.classList.add('swiping');const target=swipeTarget(dx);if(s.target!==target){gestureView?.remove();gestureView=null;s.target=target;}if(target&&!gestureView)gestureView=prepareSwipe(target,dx<0?1:-1);const move=target?dx:dx*.2;gestureSurface.style.transform=`translateX(${move}px)`;if(gestureView)gestureView.style.transform=`translateX(${dx+(dx<0?1:-1)*innerWidth}px)`;});
document.addEventListener('pointerup',e=>{const s=swipeStart;if(s&&s.pointerId!==e.pointerId)return;clearTimeout(longPressTimer);pressStart=null;swipeStart=null;if(s?.axis==='x'&&!menuRoot)completeSwipe(s,e.clientX-s.x).catch(error=>{clearSwipe();navigating=false;failure(error);});else if(!navigating)clearSwipe();});
document.addEventListener('pointercancel',()=>{clearTimeout(longPressTimer);swipeStart=null;clearSwipe();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#media-input').addEventListener('change',e=>addMedia(e.target.files,mediaProject||activeId).catch(failure));$('#backup-input').addEventListener('change',e=>readBackup(e.target.files[0]).catch(failure));
window.addEventListener('pagehide',()=>{rememberDraft();inkEditor.flush().catch(failure);noteEditor.flush().catch(failure);});document.addEventListener('visibilitychange',()=>{if(document.hidden){rememberDraft();inkEditor.flush().catch(failure);noteEditor.flush().catch(failure);}});
window.ziyanPersistNow=()=>{rememberDraft();inkEditor.flush().catch(failure);noteEditor.flush().catch(failure);};window.ziyanGoBack=()=>{if(sharePreview){sharePreview.cancel();return true;}if(menuRoot){closeMenu();return true;}if(selecting){closeSelection();return true;}if(dialog.open){closeDialog();return true;}if(document.querySelector('.note-editor')){noteEditor.back().catch(failure);return true;}const back=$('.ink-editor [data-ink-action="back"]');if(back){back.click();return true;}if(page!=='projects'){navigatePage('projects');return true;}if(inChat){inChat=false;render();return true;}rememberDraft();return false;};

// Sharing has its own modal and transaction; it never repurposes a composer/editor draft.
let sharePreview=null, checkingShares=false, sharesChanged=false;
function startShareReceiver(){
 if(!window.ZiyanShares)return;
 window.ZiyanShares.onAvailable=()=>checkShares().catch(failure);
 window.ZiyanShares.available();
}
async function checkShares(){
 if(sharePreview)return;
 if(checkingShares){sharesChanged=true;return;}
 checkingShares=true;
 try{
  do{
   sharesChanged=false;
   for(const incoming of window.ZiyanShares.list()){
    // This marker commits with the records; a crash before native cleanup cannot duplicate them.
    if(await request('meta','get','share-'+incoming.token)){window.ZiyanShares.discard(incoming.token);continue;}
    openSharePreview(incoming);return;
   }
  }while(sharesChanged);
 }finally{checkingShares=false;}
}
function openSharePreview(incoming){
 window.ziyanPersistNow();closeMenu();clearTimeout(longPressTimer);swipeStart=null;
 if(!navigating)clearSwipe();
 const root=document.createElement('dialog');root.className='share-preview';
 const state={root,cancelled:false,saving:false,files:null,urls:[],cancel(){
  if(state.saving)return;
  state.cancelled=true;window.ZiyanShares.discard(incoming.token);finish();
 }};
 sharePreview=state;
 root.innerHTML=`<form><h3>接收分享</h3><p class="dialog-copy">确认后保存到所选项目。单个附件上限 200MB。</p><label>目标项目<select id="share-project" required>${sortedProjects().map(p=>`<option value="${esc(p.id)}" ${p.id===activeId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>文字 / 链接<textarea id="share-text" maxlength="50000" class="edit-text" aria-label="分享文字">${esc(incoming.text||'')}</textarea></label><div id="share-files"></div><p id="share-status" class="dialog-copy" role="status"></p><div class="dialog-actions"><button type="button" class="secondary" id="share-cancel">取消</button><button type="button" class="secondary" id="share-retry" hidden>重试读取</button><button type="submit" class="primary" id="share-save" disabled>确认保存</button></div></form>`;
 document.body.append(root);root.showModal();
 // No app-wide click/gesture handler should process controls inside this modal.
 root.addEventListener('click',e=>e.stopPropagation());
 root.addEventListener('keydown',e=>e.stopPropagation());
 root.addEventListener('cancel',e=>{e.preventDefault();state.cancel();});
 $('#share-cancel',root).onclick=state.cancel;
 function status(text){$('#share-status',root).textContent=text;}
 function finish(){
  root.close();root.remove();state.urls.forEach(url=>URL.revokeObjectURL(url));
  if(sharePreview===state)sharePreview=null;
  checkShares().catch(failure);
 }
 async function load(){
  $('#share-retry',root).hidden=true;$('#share-save',root).disabled=true;
  state.urls.forEach(url=>URL.revokeObjectURL(url));state.urls=[];$('#share-files',root).replaceChildren();
  try{
   if(typeof incoming.text!=='string'||incoming.text.length>50000||!Array.isArray(incoming.files))throw new Error('分享内容格式不支持');
   const files=[];
   for(let i=0;i<incoming.files.length;i++){
    status(`正在读取附件 ${i+1} / ${incoming.files.length}…`);
    const file=await window.ZiyanShares.file(incoming.token,i,incoming.files[i],()=>state.cancelled);
    if(state.cancelled)return;
    files.push(file);
    const item=document.createElement('figure'),url=URL.createObjectURL(file);state.urls.push(url);
    const media=document.createElement(file.type.startsWith('image/')?'img':'video');media.src=url;
    if(media.tagName==='VIDEO'){media.controls=true;media.preload='metadata';media.playsInline=true;}
    else media.alt=file.name;
    const caption=document.createElement('figcaption');caption.textContent=file.name+' · '+(file.size/1024/1024).toFixed(2)+' MB';
    item.append(media,caption);$('#share-files',root).append(item);
   }
   if(state.cancelled)return;
   state.files=files;status(projects.length?(files.length?`共 ${files.length} 个附件，等待确认保存`:'请核对文字并确认保存'):'请先取消分享并新建项目，再重新分享');
   $('#share-save',root).disabled=!projects.length;
  }catch(e){if(!state.cancelled){state.files=null;status(e.message||'分享读取失败');$('#share-retry',root).hidden=false;}}
 }
 $('#share-retry',root).onclick=load;
 $('form',root).onsubmit=async e=>{
  e.preventDefault();e.stopPropagation();
  if(state.saving||!state.files)return;
  const text=$('#share-text',root).value.trim(),pid=$('#share-project',root).value;
  if(!text&&!state.files.length){status('请输入文字或取消分享');return;}
  if(text.length>50000){status('分享文字超过 5 万字');return;}
  if(busy){status('应用正在保存，请稍后再次确认');return;}
  state.saving=true;busy=true;$('#share-save',root).disabled=true;$('#share-cancel',root).disabled=true;
  $('#share-text',root).disabled=true;$('#share-project',root).disabled=true;
  let committed=false;
  try{
   const target=await request('projects','get',pid);if(!target)throw new Error('目标项目已不存在，请取消后重新分享');
   const now=Date.now(),records=[],media=[];
   if(text)records.push({id:id(),projectId:pid,type:'text',text,created:now});
   state.files.forEach(file=>{const mid=id();records.push({id:mid,projectId:pid,type:file.type.startsWith('image/')?'image':'video',name:file.name,created:now+records.length});media.push({id:mid,blob:file});});
   await transaction(['messages','media','projects','meta'],tx=>{
    records.forEach(m=>tx.objectStore('messages').put(m));media.forEach(m=>tx.objectStore('media').put(m));
    tx.objectStore('projects').put({...target,updated:now+records.length});
    tx.objectStore('meta').put({id:'share-'+incoming.token,value:true});
   });
   committed=true;window.ZiyanShares.discard(incoming.token);
   await refresh();render();toast(`已保存到「${target.name}」`);
  }catch(error){
   if(!committed){status(error?.name==='QuotaExceededError'?'设备空间不足，未保存任何分享记录；清理空间后可重试':error.message||'保存失败，可重试');return;}
   failure(error);
  }finally{
   state.saving=false;busy=false;
   if(!committed){$('#share-save',root).disabled=false;$('#share-cancel',root).disabled=false;$('#share-text',root).disabled=false;$('#share-project',root).disabled=false;}
  }
  finish();
 };
 load();
}

async function migrateTasks(){const old=await request('messages','getAll');const legacy=old.filter(m=>m.type==='task');if(!legacy.length)return;const ps=await request('projects','getAll');await transaction(['tasks','messages','projects'],tx=>{legacy.forEach(m=>{tx.objectStore('tasks').put({id:m.id,projectId:m.projectId,text:m.text,done:!!m.done,created:m.created});tx.objectStore('messages').delete(m.id);});ps.filter(p=>legacy.some(t=>t.projectId===p.id)).forEach(p=>tx.objectStore('projects').put({...p,tasksOpen:true}));});}
async function start(){if(!globalThis.indexedDB||!globalThis.crypto?.randomUUID)throw new Error('请使用支持本地存储的 Chrome 打开应用');db=await new Promise((resolve,reject)=>{const r=indexedDB.open('ziyan-local-v1',2);r.onupgradeneeded=()=>{for(const name of [...STORES,'meta'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>toast('请关闭其他自言页面后重新打开');});db.onversionchange=()=>{db.close();toast('数据版本已更新，请刷新');};await migrateTasks();await refresh();const stored=await request('drafts','getAll');stored.forEach(d=>drafts.set(d.id,d));const initialized=await request('meta','get','initialized');if(!initialized){const now=Date.now();if(!projects.length)await request('projects','put',{id:id(),name:'随手记',emoji:'🌱',color:0,pinned:false,created:now,updated:now,tasksOpen:false});await request('meta','put',{id:'initialized',value:true});}if(!await request('meta','get','templates-initialized')){if(!templates.length)await transaction(['templates'],tx=>DEFAULT_TEMPLATES.forEach(t=>tx.objectStore('templates').put(t)));await request('meta','put',{id:'templates-initialized',value:true});}await refresh();taskMode=!!draft().taskMode;render(true);startShareReceiver();if(!window.ZiyanAndroid && 'serviceWorker' in navigator && window.isSecureContext && ['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>toast('离线缓存未启用，请刷新重试'));}
start().catch(e=>{app.innerHTML=`<div class="empty"><h2>暂时无法打开</h2><p>${esc(e.message)}</p></div>`;console.error(e);});
